using System.Text.Json;
using InformesAvanzar.Api.Bitrix;
using Npgsql;
namespace InformesAvanzar.Api.Data;
public static class OrganizationQueries {
 private sealed record DepartmentItem(string Id,string Name,string? ParentId,string? HeadId);
 public static async Task EnsureSchemaAsync(NpgsqlDataSource ds,CancellationToken ct){await using var connection=await ds.OpenConnectionAsync(ct);await using var command=new NpgsqlCommand("""CREATE TABLE IF NOT EXISTS reporting.organization_access (department_id text PRIMARY KEY, role_label text NOT NULL DEFAULT 'viewer', visible_reports text[] NOT NULL DEFAULT ARRAY[]::text[], visible_blocks text[] NOT NULL DEFAULT ARRAY[]::text[], updated_at timestamptz NOT NULL DEFAULT now()); ALTER TABLE reporting.organization_access ADD COLUMN IF NOT EXISTS visible_blocks text[] NOT NULL DEFAULT ARRAY[]::text[]; CREATE TABLE IF NOT EXISTS reporting.user_report_block_settings (user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, report_code text NOT NULL, visible_blocks text[] NOT NULL DEFAULT ARRAY[]::text[], updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,report_code));""",connection);await command.ExecuteNonQueryAsync(ct);}
 public static async Task SetSettingsAsync(string departmentId,string? email,string roleLabel,string[] visibleReports,string[] visibleBlocks,NpgsqlDataSource ds,CancellationToken ct){const string sql="""INSERT INTO reporting.organization_access(department_id,role_label,visible_reports,visible_blocks,updated_at) VALUES(@id,@role,@reports,@blocks,now()) ON CONFLICT(department_id) DO UPDATE SET role_label=EXCLUDED.role_label,visible_reports=EXCLUDED.visible_reports,visible_blocks=EXCLUDED.visible_blocks,updated_at=now();""";await using var connection=await ds.OpenConnectionAsync(ct);await using var transaction=await connection.BeginTransactionAsync(ct);await using(var command=new NpgsqlCommand(sql,connection,transaction)){command.Parameters.AddWithValue("id",departmentId);command.Parameters.AddWithValue("role",roleLabel is "coordinator" or "leader" or "advisor" ? roleLabel : "viewer");command.Parameters.AddWithValue("reports",visibleReports);command.Parameters.AddWithValue("blocks",visibleBlocks);await command.ExecuteNonQueryAsync(ct);}if(!string.IsNullOrWhiteSpace(email)){Guid? userId=null;await using(var find=new NpgsqlCommand("SELECT id FROM auth.users WHERE lower(email)=lower(@email) AND deleted_at IS NULL;",connection,transaction)){find.Parameters.AddWithValue("email",email.Trim());userId=await find.ExecuteScalarAsync(ct) as Guid?;}if(userId is not null){await using(var blockCommand=new NpgsqlCommand("""INSERT INTO reporting.user_report_block_settings(user_id,report_code,visible_blocks,updated_at) VALUES(@userId,'informe_general_comercial',@blocks,now()) ON CONFLICT(user_id,report_code) DO UPDATE SET visible_blocks=EXCLUDED.visible_blocks,updated_at=now();""",connection,transaction)){blockCommand.Parameters.AddWithValue("userId",userId.Value);blockCommand.Parameters.AddWithValue("blocks",visibleBlocks);await blockCommand.ExecuteNonQueryAsync(ct);}var managedReports=new[]{"informe_general_comercial","fuerza_comercial_diego","rch_comercial"};await using(var clear=new NpgsqlCommand("DELETE FROM reporting.report_access ra USING reporting.report_definitions rd WHERE ra.report_definition_id=rd.id AND ra.user_id=@userId AND rd.code=ANY(@managedReports);",connection,transaction)){clear.Parameters.AddWithValue("userId",userId.Value);clear.Parameters.AddWithValue("managedReports",managedReports);await clear.ExecuteNonQueryAsync(ct);}await using(var grant=new NpgsqlCommand("""INSERT INTO reporting.report_access(report_definition_id,user_id,access_level) SELECT id,@userId,'viewer' FROM reporting.report_definitions WHERE code=ANY(@reports) ON CONFLICT(report_definition_id,user_id) WHERE user_id IS NOT NULL DO UPDATE SET access_level='viewer';""",connection,transaction)){grant.Parameters.AddWithValue("userId",userId.Value);grant.Parameters.AddWithValue("reports",visibleReports);await grant.ExecuteNonQueryAsync(ct);}}}await transaction.CommitAsync(ct);}
 public static async Task<(bool Configured,string[] Blocks)> GetUserBlockAccessAsync(Guid userId,string reportCode,NpgsqlDataSource ds,CancellationToken ct){await using var connection=await ds.OpenConnectionAsync(ct);await using var command=new NpgsqlCommand("SELECT visible_blocks FROM reporting.user_report_block_settings WHERE user_id=@userId AND report_code=@reportCode;",connection);command.Parameters.AddWithValue("userId",userId);command.Parameters.AddWithValue("reportCode",reportCode);var value=await command.ExecuteScalarAsync(ct);return value is string[] blocks?(true,blocks):(false,Array.Empty<string>());}
 public static async Task<object> GetCommercialStructureAsync(IBitrixClient client,NpgsqlDataSource ds,CancellationToken ct){
  using var response=await client.CallAsync("department.get",Array.Empty<KeyValuePair<string,string>>(),ct);
  if(!response.RootElement.TryGetProperty("result",out var result)||result.ValueKind!=JsonValueKind.Array)return new{departments=Array.Empty<object>()};
  var source=result.EnumerateArray().Select(x=>new DepartmentItem(x.GetProperty("ID").GetString()??"0",x.TryGetProperty("NAME",out var n)?n.GetString()??"Departamento":"Departamento",x.TryGetProperty("PARENT",out var p)&&p.ValueKind!=JsonValueKind.Null?p.ToString():null,x.TryGetProperty("UF_HEAD",out var h)&&h.ValueKind!=JsonValueKind.Null&&h.ToString()!="0"?h.ToString():null)).ToList();
  async Task AddDepartmentsAsync(string key,string value){using var extra=await client.CallAsync("department.get",new[]{new KeyValuePair<string,string>(key,value)},ct);if(!extra.RootElement.TryGetProperty("result",out var items)||items.ValueKind!=JsonValueKind.Array)return;foreach(var x in items.EnumerateArray()){var item=new DepartmentItem(x.GetProperty("ID").GetString()??"0",x.TryGetProperty("NAME",out var n)?n.GetString()??"Departamento":"Departamento",x.TryGetProperty("PARENT",out var p)&&p.ValueKind!=JsonValueKind.Null?p.ToString():null,x.TryGetProperty("UF_HEAD",out var h)&&h.ValueKind!=JsonValueKind.Null&&h.ToString()!="0"?h.ToString():null);if(source.All(current=>current.Id!=item.Id))source.Add(item);}}
  await AddDepartmentsAsync("ID","1236");await AddDepartmentsAsync("PARENT","1236");
  await AddDepartmentsAsync("ID","22");await AddDepartmentsAsync("PARENT","22");
  await AddDepartmentsAsync("ID","1422");
  var ids=new HashSet<string>{"646"};var added=true;while(added){added=false;foreach(var x in source.Where(x=>x.ParentId is not null&&ids.Contains(x.ParentId)))added|=ids.Add(x.Id);}var commercial=source.Where(x=>ids.Contains(x.Id)).ToArray();
  var counts=new Dictionary<string,int>();var heads=new Dictionary<string,(string Name,string? Email)>();var localUsers=new Dictionary<string,Guid>(StringComparer.OrdinalIgnoreCase);var settings=new Dictionary<string,(string Role,string[] Reports,string[] Blocks)>();await using var connection=await ds.OpenConnectionAsync(ct);
  const string sql="""WITH latest AS (SELECT DISTINCT ON (bitrix_id) bitrix_id,payload FROM bitrix.raw_payloads WHERE entity_type='user' ORDER BY bitrix_id,received_at DESC), assigned AS (SELECT jsonb_array_elements_text(payload->'UF_DEPARTMENT') department_id FROM latest WHERE jsonb_typeof(payload->'UF_DEPARTMENT')='array') SELECT department_id,COUNT(*)::int FROM assigned WHERE department_id=ANY(@ids) GROUP BY department_id;""";
  await using(var cmd=new NpgsqlCommand(sql,connection)){cmd.Parameters.AddWithValue("ids",commercial.Select(x=>x.Id).ToArray());await using var reader=await cmd.ExecuteReaderAsync(ct);while(await reader.ReadAsync(ct))counts[reader.GetString(0)]=reader.GetInt32(1);}
  await using(var cmd=new NpgsqlCommand("SELECT bitrix_id,full_name,email FROM bitrix.users WHERE bitrix_id=ANY(@ids);",connection)){cmd.Parameters.AddWithValue("ids",commercial.Where(x=>x.HeadId is not null).Select(x=>x.HeadId!).Distinct().ToArray());await using var reader=await cmd.ExecuteReaderAsync(ct);while(await reader.ReadAsync(ct))heads[reader.GetString(0)]=(reader.GetString(1),reader.IsDBNull(2)?null:reader.GetString(2));}
  await using(var cmd=new NpgsqlCommand("SELECT lower(email),id FROM auth.users WHERE deleted_at IS NULL;",connection)){await using var reader=await cmd.ExecuteReaderAsync(ct);while(await reader.ReadAsync(ct))localUsers[reader.GetString(0)]=reader.GetGuid(1);}
  await using(var cmd=new NpgsqlCommand("SELECT department_id,role_label,visible_reports,visible_blocks FROM reporting.organization_access WHERE department_id=ANY(@ids);",connection)){cmd.Parameters.AddWithValue("ids",commercial.Select(x=>x.Id).ToArray());await using var reader=await cmd.ExecuteReaderAsync(ct);while(await reader.ReadAsync(ct))settings[reader.GetString(0)]=(reader.GetString(1),reader.GetFieldValue<string[]>(2),reader.GetFieldValue<string[]>(3));}
  return new{departments=commercial.Select(x=>{var headName=x.HeadId is not null&&heads.TryGetValue(x.HeadId,out var h)?h.Name:null;var headEmail=x.HeadId is not null&&heads.TryGetValue(x.HeadId,out h)?h.Email:null;var localUserId=Guid.Empty;var userExists=!string.IsNullOrWhiteSpace(headEmail)&&localUsers.TryGetValue(headEmail,out localUserId);return new{id=x.Id,name=x.Name,parentId=x.ParentId,headId=x.HeadId,headName,headEmail,directUsers=counts.GetValueOrDefault(x.Id),roleLabel=settings.TryGetValue(x.Id,out var s)?s.Role:"viewer",visibleReports=settings.TryGetValue(x.Id,out s)?s.Reports:Array.Empty<string>(),visibleBlocks=settings.TryGetValue(x.Id,out s)?s.Blocks:Array.Empty<string>(),userExists,localUserId=userExists?localUserId:(Guid?)null};})};
 }
}
